import clsx from 'clsx';
import React from 'react';

import { bottom, magnifier } from './Magnifier.sty.js';
import { useOverlaysEvents } from '../../../hooks/useOverlaysEvents.js';
import { useMagnifierPosition } from '../hooks/useMagnifierPosition.js';

export function BottomMagnifier(props: {
  label: string;
  mouseX: number;
  offset: number;
}) {
  const { label, mouseX, offset } = props;

  const { chartBounds } = useOverlaysEvents();

  const { magnifierPosition: left, magnifierRef } = useMagnifierPosition(
    mouseX,
    chartBounds?.left ?? 0,
    chartBounds?.right ?? 0,
    'horizontal',
  );
  const top = (chartBounds?.bottom ?? 0) + offset;

  return (
    <div
      data-testid="x-axis-magnifier"
      ref={magnifierRef}
      className={clsx(magnifier, bottom)}
      style={{ top, left }}
    >
      {label}
    </div>
  );
}
